INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (11, 25, 'theory', 'Quiz: Forms and Storage');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 25, 0, 'Which fields end up in the form data on submit?', '["All fields", "Only visible ones", "Only those with a name attribute that are not disabled; of checkboxes, the checked ones", "Only text"]', 2, 'Fields without a name and disabled fields do not go into the data, and a button only does if it was the one pressed.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 25, 1, 'Why can''t you rely on client-side validation alone?', '["A request can be sent bypassing the form, so the server must check again", "Browsers do not support it", "It is too slow", "It is forbidden"]', 0, 'Client-side checking is a convenience for the user, not protection.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 25, 2, 'Which cookie attribute hides it from JavaScript?', '["Secure", "SameSite", "Path", "HttpOnly"]', 3, 'HttpOnly forbids reading through document.cookie — that is why the session ID is stored this way.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 25, 3, 'What is special about localStorage?', '["Asynchronous and unlimited", "Synchronous, stores strings, quota about 5 MB, data is available to any page script", "Cleared when the tab closes", "Sent with every request"]', 1, 'For large volumes and queries you use IndexedDB, and secrets are not kept in localStorage.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 25, 4, 'What does history.pushState do?', '["Reloads the page", "Deletes the history", "Adds a history entry and changes the address without a reload", "Sends a request to the server"]', 2, 'When the user presses back, the popstate event fires — single-page app routers are built on it.');
